import{_ as n,o as r,c as t,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Teil 3: Das Schicksal der Verlierer","description":"","frontmatter":{},"headers":[],"relativePath":"drehbuch/teil-3-das-schicksal-der-verlierer.md","filePath":"drehbuch/teil-3-das-schicksal-der-verlierer.md"}'),s={name:"drehbuch/teil-3-das-schicksal-der-verlierer.md"};function a(h,e,l,o,d,g){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="teil-3-das-schicksal-der-verlierer" tabindex="-1">Teil 3: Das Schicksal der Verlierer <a class="header-anchor" href="#teil-3-das-schicksal-der-verlierer" aria-label="Permalink to &quot;Teil 3: Das Schicksal der Verlierer&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Vom Verschwinden der Namen</em></p><p><strong>Besetzung:</strong> Oliver Masucci (Alfred Alsberg / Heinz Alsberg), August Diehl (Der junge Helmut / Ein fiktiver Restitutionsbeamter), Birgit Minichmayr (Martha Alsberg / Die Stimme der Gegenwart).</p><hr><h2 id="szene-1-amsterdam-1939-–-das-warten-im-porzellanladen" tabindex="-1">Szene 1: Amsterdam 1939 – Das Warten im Porzellanladen <a class="header-anchor" href="#szene-1-amsterdam-1939-–-das-warten-im-porzellanladen" aria-label="Permalink to &quot;Szene 1: Amsterdam 1939 – Das Warten im Porzellanladen&quot;">​</a></h2><p><strong>Ort:</strong> Eine kleine, überfüllte Wohnung in Amsterdam. Überall stehen Kisten. <strong>Zeit:</strong> Kurz vor der deutschen Besetzung der Niederlande.</p><p>Alfred Alsberg (Oliver Masucci) sitzt an einem wackeligen Tisch. Er versucht, eine Liste seines verbliebenen Eigentums zu erstellen. Seine Frau Martha (Birgit Minichmayr) packt Silberbesteck in Zeitungspapier.</p><p><strong>ALFRED</strong> (bitter) Sie haben das Kaufhaus in Duisburg jetzt „Horten“ genannt. Sie haben nicht einmal die Fassade geändert. Nur die Buchstaben über der Tür. Als ob man eine Seele einfach mit Schmirgelpapier entfernen könnte.</p><p><strong>MARTHA</strong> Wir sind hier sicher, Alfred. Helmut Horten ist weit weg. Er hat, was er wollte. Er wird uns nicht folgen.</p><p><strong>ALFRED</strong> Er folgt uns nicht, Martha. Er überholt uns. Er nutzt den Wind, der uns vertreibt, um seine Segel zu füllen.</p><hr><h2 id="szene-2-der-telefon-dialog-der-ohnmacht-neu" tabindex="-1">Szene 2: Der Telefon-Dialog der Ohnmacht (NEU) <a class="header-anchor" href="#szene-2-der-telefon-dialog-der-ohnmacht-neu" aria-label="Permalink to &quot;Szene 2: Der Telefon-Dialog der Ohnmacht (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Geteilter Bildschirm. Links: Alfred in Amsterdam. Rechts: Helmut (August Diehl) in seinem neuen Luxusbüro. <strong>Zeit:</strong> Winter 1939.</p><p><strong>ALFRED</strong> (ins Telefon) Herr Horten, ich verlange die Restzahlung. Der Vertrag sah eine Summe vor, die wir für unsere Visa brauchen.</p><p><strong>HELMUT</strong> (ruhig, blättert in Akten) Herr Dr. Alsberg. Ich verstehe Ihre... emotionale Lage. Aber die Devisenbestimmungen haben sich verschärft. Das Geld liegt auf einem Sperrkonto. Ich habe keinen Zugriff mehr. Es ist jetzt... Staatsangelegenheit.</p><p><strong>ALFRED</strong> Sie haben das Konto gesperrt, Helmut! Sie haben dem Staat den Tipp gegeben!</p><p><strong>HELMUT</strong> (kalt) Ich optimiere nur die Abläufe. Das ist kaufmännische Sorgfaltspflicht. Ich wünsche Ihnen eine gute Reise. Wohin auch immer sie führen mag.</p><p>Helmut legt auf. Er wischt sich den Hörer mit einem weißen Tuch ab.</p><hr><h2 id="szene-3-der-„stolperstein-dialog-–-meta-ebene-neu" tabindex="-1">Szene 3: Der „Stolperstein-Dialog“ – Meta-Ebene (NEU) <a class="header-anchor" href="#szene-3-der-„stolperstein-dialog-–-meta-ebene-neu" aria-label="Permalink to &quot;Szene 3: Der „Stolperstein-Dialog“ – Meta-Ebene (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Die Bahnhofstraße in Gelsenkirchen in der Gegenwart. <strong>Zeit:</strong> Ein regnerischer Nachmittag.</p><p>Wir sehen die Stolpersteine für Alfred, Emma und Martha Alsberg im Boden. Plötzlich treten die Charaktere aus dem Schatten der heutigen Geschäfte. Sie sind halb-transparent, wirken wie Projektionen.</p><p><strong>ALFRED (GEIST)</strong> Sie laufen über uns drüber, Martha. Jeden Tag. Sie suchen nach Schnäppchen.</p><p><strong>MARTHA (GEIST)</strong> Es ist ein guter Platz, Alfred. Man hört das Rascheln der Einkaufstüten. Das ist das Geräusch, das Helmut so liebte.</p><p><strong>HELMUT (GEIST)</strong> (tritt hinzu, elegant wie eh und je) Es ist kein schlechtes Geräusch. Es ist das Geräusch des Marktes. Der Markt verzeiht nicht. Er bereinigt sich einfach. Ihr seid... statistisches Rauschen geworden. Ein kleiner Punkt in einem sehr großen Bild.</p><hr><h2 id="szene-4-die-flucht-ins-ungewisse-neu" tabindex="-1">Szene 4: Die Flucht ins Ungewisse (NEU) <a class="header-anchor" href="#szene-4-die-flucht-ins-ungewisse-neu" aria-label="Permalink to &quot;Szene 4: Die Flucht ins Ungewisse (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Der Hafen von Rotterdam. <strong>Zeit:</strong> 1940, kurz vor dem Angriff.</p><p>Szenen der Hektik. Alfred versucht, seine Kinder Eva, Fritz und Heinz auf ein Schiff zu bringen. Es ist eine verzweifelte Choreografie der Trennung.</p><p><strong>ALFRED</strong> (zu Heinz, gespielt vom jungen Masucci) Vergiss den Namen nicht. Aber sag ihn niemandem. Ein Name kann eine Festung sein – oder ein Gefängnis.</p><p><strong>CHRONIST (Masucci, Off-Stimme)</strong> Während die Alsbergs um ihr nacktes Leben verhandelten, verhandelte Helmut Horten bereits über die nächste Expansion. Für ihn war der Krieg eine logistische Herausforderung. Für sie war er das Ende der Welt.</p><hr><h2 id="szene-5-das-kafkaeske-amt-fur-wiedergutmachung-neu" tabindex="-1">Szene 5: Das Kafkaeske Amt für Wiedergutmachung (NEU) <a class="header-anchor" href="#szene-5-das-kafkaeske-amt-fur-wiedergutmachung-neu" aria-label="Permalink to &quot;Szene 5: Das Kafkaeske Amt für Wiedergutmachung (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein graues, staubiges Büro in der Nachkriegszeit (1952). <strong>Zeit:</strong> Ein endloser Nachmittag.</p><p>Heinz Alsberg (Oliver Masucci) sitzt einem Beamten (August Diehl) gegenüber. Der Beamte trägt Ärmelschoner und raucht eine Zigarre, die nach billigem Staatsdienst riecht. Heinz legt eine zerschlissene Kopie des Arisierungs-Protokolls vom 1. Mai 1938 auf den Tisch.</p><p><strong>HEINZ</strong> Hier ist es. Das Protokoll der Übernahme. Mein Vater hat es damals unter Zwang unterschrieben. Er hat es mir vor seiner Deportation nach Litzmannstadt zugesteckt. „Dieses Papier ist unser Recht“, hat er gesagt.</p><p><strong>BEAMTE</strong> (nimmt das Papier mit zwei Fingern hoch, als wäre es unrein) Litzmannstadt... ja, tragisch. Aber dieses Dokument, Herr Alsberg... das ist nur eine Absichtserklärung. Wo ist der notarielle Hauptvertrag? Wo ist der Nachweis, dass der Kaufpreis nicht doch geflossen ist?</p><p><strong>HEINZ</strong> Der Kaufpreis lag auf einem Sperrkonto! Helmut Horten wusste, dass wir nie an das Geld kommen würden. Er hat mit dem Staat paktiert, um uns auszuhungern!</p><p><strong>BEAMTE</strong> (lächelt mitleidig) Paktieren ist ein hartes Wort. Nennen wir es... Kooperation in schwierigen Zeiten. Herr Horten ist ein angesehener Steuerzahler, er hat Duisburg nach dem Krieg wieder aufgebaut. Wir können seinen Ruf nicht durch solche... emotionalen Anschuldigungen gefährden.</p><p><strong>HEINZ</strong> Mein Vater ist dort verhungert, während Horten in seinem Büro den Champagner kühlte! Er starb im November 1943 in Litzmannstadt. Wollen Sie mir sagen, dass das auch „Kooperation“ war?</p><p><strong>BEAMTE</strong> (bläst den Rauch in Heinz&#39; Gesicht) Ohne den notariellen Hauptvertrag keine Restitution. Ich habe hier noch zweihundert weitere Fälle auf dem Tisch, Herr Alsberg. Die Zeit heilt alle Wunden... oder sie lässt sie verjähren. Nächster, bitte!</p><hr><h2 id="szene-6-die-geister-der-kaufhauser-neu" tabindex="-1">Szene 6: Die Geister der Kaufhäuser (NEU) <a class="header-anchor" href="#szene-6-die-geister-der-kaufhauser-neu" aria-label="Permalink to &quot;Szene 6: Die Geister der Kaufhäuser (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> In einem modernen Horten-Warenhaus bei Nacht. <strong>Zeit:</strong> Gegenwart.</p><p>Die Kamera schwebt durch die Parfümerie-Abteilung. Plötzlich hören wir das Flüstern der Vergangenheit. Namen von Mitarbeitern, die 1933 entlassen wurden, hallen durch die Gänge.</p><p><strong>STIMME (Off)</strong> Josephs... Neuss... deportiert... Alsberg... Köln... Theresienstadt...</p><p>Die Reinigungskräfte arbeiten ungerührt weiter. Sie polieren den Boden so glatt, dass man sein eigenes Spiegelbild nicht mehr erkennt. Nur noch die Ware.</p><hr><h2 id="szene-7-der-„restitutions-tanz-neu" tabindex="-1">Szene 7: Der „Restitutions-Tanz“ (NEU) <a class="header-anchor" href="#szene-7-der-„restitutions-tanz-neu" aria-label="Permalink to &quot;Szene 7: Der „Restitutions-Tanz“ (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein Gerichtssaal, der sich langsam in ein Kabarett-Bühnenbild verwandelt. <strong>Zeit:</strong> 1950er Jahre.</p><p>Anwälte in schwarzen Roben tanzen um Heinz Alsberg herum. Sie werfen mit Paragrafen-Zetteln wie mit Konfetti.</p><p><strong>ANWALT 1</strong> Verjährungsfrist! <strong>ANWALT 2</strong> Kaufmännische Gutgläubigkeit! <strong>ANWALT 3</strong> Marktwert-Anpassung!</p><p>Heinz steht in der Mitte, er wird immer kleiner, während die Aktenberge um ihn herum wachsen. Helmut Horten (Diehl) sitzt in der letzten Reihe und lächelt. Er bietet Heinz eine Praline an.</p><hr><h2 id="szene-8-das-vermachtnis-des-schweigens-neu" tabindex="-1">Szene 8: Das Vermächtnis des Schweigens (NEU) <a class="header-anchor" href="#szene-8-das-vermachtnis-des-schweigens-neu" aria-label="Permalink to &quot;Szene 8: Das Vermächtnis des Schweigens (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein Friedhof in England. <strong>Zeit:</strong> Viel später.</p><p>Eva Alsberg steht am Grab ihrer Eltern. Sie spricht nicht. Sie hält nur eine alte Quittung aus dem Duisburger Kaufhaus in der Hand. Ein kleiner Zettel, auf dem noch „Alsberg“ steht, überstempelt mit einem fetten „HORTEN“.</p><p><strong>CHRONIST (Off)</strong> Am Ende bleibt nicht das Geld. Es bleibt das Schweigen. Ein Schweigen, das so teuer erkauft wurde, dass es heute als Diskretion bezeichnet wird. Aber wenn man genau hinhört... zwischen dem Klicken der Absätze und dem Piepsen der Scanner... dann hört man sie noch. Die Namen, die keiner mehr aussprechen will.</p><p><strong>FADE OUT.</strong></p>',59)])])}const m=n(s,[["render",a]]);export{c as __pageData,m as default};
